mapper.select:
select f.id, f.field_type, f.field_id, f.field_name, f.category_id, f.data_type, f.unit, f.mode,
       f.description, cast(f.value_type_config as varchar) as value_type_config, f.metadata_config, f.search_keywords, f.use_count, f.status, f.tenant_id,
       f.create_by, f.create_time, f.update_by, f.update_time,
       c.category_name
from iot_standard_metadata_field f
left join iot_standard_category c on f.category_id = c.id

  and f.field_type = #{fieldType}
  and f.field_id like concat('%', #{fieldId}, '%')
  and f.field_name like concat('%', #{fieldName}, '%')
  and f.category_id = #{categoryId}
  and f.data_type = #{dataType}
  and f.status = #{status}
  and f.tenant_id = #{tenantId}

order by f.use_count desc, f.id desc


where field_type = #{fieldType} and status = 1
and tenant_id = #{tenantId}
order by use_count desc, id desc


where status = 1
and field_type = #{fieldType}
and tenant_id = #{tenantId}
and (field_id like concat('%', #{keyword}, '%')
     or field_name like concat('%', #{keyword}, '%')
     or search_keywords like concat('%', #{keyword}, '%')
     or description like concat('%', #{keyword}, '%'))
order by use_count desc, id desc
limit #{limit}

mapper.update:
update iot_standard_metadata_field
field_type = #{fieldType}, field_id = #{fieldId}, field_name = #{fieldName}, category_id = #{categoryId}, data_type = #{dataType}, unit = #{unit}, mode = #{mode}, description = #{description}, value_type_config = CAST(#{valueTypeConfig} AS JSON), metadata_config = #{metadataConfig}, search_keywords = #{searchKeywords}, status = #{status}, tenant_id = #{tenantId}, update_by = #{updateBy}, update_time = now()
where id = #{id} and tenant_id = #{tenantId}

update iot_standard_metadata_field
set use_count = use_count + 1
where id = #{id}
and tenant_id = #{tenantId}

