delete from iot_standard_metadata_field where id in

  #{id}

and tenant_id = #{tenantId}

mapper.select:
select count(*) from iot_standard_metadata_field
where field_type = #{fieldType} and field_id = #{fieldId}
and id != #{excludeId}
and tenant_id = #{tenantId}


where status = 1
and field_type = #{fieldType}
and tenant_id = #{tenantId}
order by use_count desc
limit #{limit}

SELECT f.*
FROM iot_standard_metadata_field f
INNER JOIN iot_standard_field_category_rel r ON f.id = r.field_id
WHERE r.category_id = #{categoryId}
  AND f.field_type = #{fieldType}
  AND f.status = 1
  AND f.tenant_id = #{tenantId}
ORDER BY f.recommend_priority DESC, f.use_count DESC, f.update_time DESC

  LIMIT #{limit}
